function ftNorm(s) { return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); }

function ftPick(seed, n) {
  const s = String(seed == null ? '' : seed);
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  return h % (n > 0 ? n : 1);
}

function verticalOf(cand) {
  const c = (cand && cand.canonical) || {};
  const explicit = ftNorm(c.vertical || (cand && cand.vertical) || '');
  if (['corredoras', 'clinicas', 'casinos_colegios', 'casinos_empresas'].includes(explicit)) return explicit;
  const ind = ftNorm((c.industry || (cand && cand.industry) || '')).trim();
  if (['corredoras', 'clinicas', 'casinos_colegios', 'casinos_empresas'].includes(ind)) return ind; // el Gateway guarda vertical→industry
  const t = ftNorm([cand && cand.company_name, c.industry, cand && cand.industry, cand && cand.domain, c.website].join(' '));
  const food = /\b(casino|casinos|cafeteria|cafeterias|comedor|comedores|concesion|concesionaria|concesionario|alimentacion|almuerzo|almuerzos|colaciones|catering|banqueteria|servicios de alimentacion)\b/.test(t);
  const school = /\b(colegio|colegios|escolar|escolares|liceo|escuela|jardin infantil|alumnos|apoderados|sostenedor)\b/.test(t);
  if (food && school) return 'casinos_colegios';
  if (food) return 'casinos_empresas';
  if (/\b(corredor de propiedades|corredora de propiedades|corredores de propiedades|corredoras de propiedades|inmobiliaria|inmobiliarias|propiedades|propiedad|corretaje|bienes raices|arriendo de (casas|departamentos|propiedades|oficinas|inmuebles)|administracion de arriendos)\b/.test(t)) return 'corredoras';
  if (/\b(clinica|clinicas|dental|dentista|dentistas|odontolog\w*|veterinari\w*|kinesiolog\w*|psicolog\w*|fonoaudiolog\w*|nutricionista|centro medico|centro de salud|medic[oa]s?|podolog\w*|oftalmolog\w*|pediatr\w*|laboratorio clinico)\b/.test(t)) return 'clinicas';
  return null;
}

function addBusinessDaysIso(ms, n, tz) {
  let t = ms, left = Math.max(0, Math.trunc(n));
  while (left > 0) { t += 24 * 3600000; const p = zonedParts(t, tz); if (p.dow >= 1 && p.dow <= 5) left--; }
  const p = zonedParts(t, tz);
  return new Date(t - ((p.hh - 10) * 60 + p.mm) * 60000).toISOString();
}

function b64url(buf) { return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }

function buildMime(o) {
  const from = o.from_name ? encodeHeader(o.from_name) + ' <' + o.from + '>' : o.from;
  const domain = emailDomain(o.from) || 'atacamalabs.cl';
  const messageId = o.message_id || '<' + newId() + '@' + domain + '>';
  const common = [
    'From: ' + from, 'To: ' + o.to, 'Subject: ' + encodeHeader(o.subject), 'Date: ' + new Date(o.now || Date.now()).toUTCString(), 'Message-ID: ' + messageId, 'MIME-Version: 1.0',
    'List-Unsubscribe: <mailto:' + o.from + '?subject=baja>',
    ...(o.in_reply_to ? ['In-Reply-To: ' + o.in_reply_to, 'References: ' + (o.references || o.in_reply_to)] : []),
  ];
  const part = (type, data) => 'Content-Type: ' + type + '; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n' + wrap76(Buffer.from(String(data || ''), 'utf8').toString('base64'));
  if (!o.html) return { raw: b64url(common.concat(['Content-Type: text/plain; charset=UTF-8', 'Content-Transfer-Encoding: base64']).join('\r\n') + '\r\n\r\n' + wrap76(Buffer.from(String(o.text || ''), 'utf8').toString('base64'))), message_id: messageId };
  const tag = String(messageId).replace(/[^a-z0-9]/gi, '').slice(0, 24) || 'x';
  const alt = 'alt_' + tag, rel = 'rel_' + tag;
  const related = ['--' + rel, part('text/html', o.html)];
  if (o.inline_png_b64) related.push('--' + rel, 'Content-Type: image/png; name="logo-atacama-labs.png"\r\nContent-Transfer-Encoding: base64\r\nContent-ID: <atacama-logo>\r\nContent-Disposition: inline; filename="logo-atacama-labs.png"\r\n\r\n' + wrap76(o.inline_png_b64));
  if (o.inline_foto_b64) related.push('--' + rel, 'Content-Type: image/png; name="christian-wevar.png"\r\nContent-Transfer-Encoding: base64\r\nContent-ID: <atacama-foto>\r\nContent-Disposition: inline; filename="christian-wevar.png"\r\n\r\n' + wrap76(o.inline_foto_b64));
  related.push('--' + rel + '--');
  const body = ['--' + alt, part('text/plain', o.text), '--' + alt, 'Content-Type: multipart/related; boundary="' + rel + '"\r\n', related.join('\r\n'), '--' + alt + '--', ''].join('\r\n');
  return { raw: b64url(common.concat(['Content-Type: multipart/alternative; boundary="' + alt + '"']).join('\r\n') + '\r\n\r\n' + body), message_id: messageId };
}

function canonicalEmails(cand) {
