function nextWindowStart(ms, cfg) {
  const step = 5 * 60 * 1000;
  let t = Math.ceil(ms / step) * step;
  for (let i = 0; i < 12 * 24 * 10; i++) { if (inSendWindow(t, cfg)) return t; t += step; }
  return ms;
}

function normEmail(e) { return String(e == null ? '' : e).trim().toLowerCase().replace(/^mailto:/, ''); }

