  if (sentSame) return fail('ya_enviado', 'Ya se envió un correo de tipo «' + kind + '» a este prospecto: un solo envío por tipo (usa seguimiento o respuesta).');
  const initialSent = history.find((m) => m.kind === 'initial' && m.direction === 'outbound' && m.status === 'sent');
  if (kind !== 'initial' && !initialSent && kind !== 'reply') return fail('sin_primer_correo', 'Un seguimiento solo existe después de enviar el primer correo.');
  const canon = cand.canonical || {};
  const contact = canon.contact || {};
  const published = [contact.email].concat(canon.emails || []).filter(Boolean);
  const to = normEmail(req.to_email || (live && live.to_email) || contact.email || (initialSent && initialSent.to_email) || '');
  const drafts = cand.drafts || {};
  const inboundMsg = kind === 'reply' ? history.filter((m) => m.direction === 'inbound' && m.gmail_thread_id).sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)))[0] : null;
  if (kind === 'reply' && !inboundMsg) return fail('sin_respuesta_previa', 'No hay una respuesta del prospecto a la que contestar.');
  let subject = req.subject != null ? req.subject : (live ? live.subject : null);
  let body = req.body != null ? req.body : (live ? live.body : null);
  if (subject == null || body == null) {
    if (kind === 'initial') { subject = subject != null ? subject : (drafts.email_subject || null); body = body != null ? body : (drafts.email_body || null); }
    else if (kind === 'reply') { if (subject == null) subject = 'Re: ' + String((inboundMsg && inboundMsg.subject) || (initialSent && initialSent.subject) || 'Atacama Labs').replace(/^re:s*/i, ''); }
    else { const t = followupTemplate(kind, cand, initialSent && initialSent.subject, initialSent && initialSent.body); subject = subject != null ? subject : t.subject; body = body != null ? body : t.body; }
  }
  if (subject != null || body != null) { const cl = cleanDraftText(subject, body, { capitalize: kind === 'initial' }); subject = cl.subject; body = cl.body; }
  if (subject == null || body == null) return fail('sin_contenido', kind === 'reply' ? 'Redacta la respuesta (body) para guardarla como borrador.' : 'No hay borrador base: indica subject y body.');
  const inbound = inboundMsg;
  const v = validateDraft({ to_email: to, subject, body }, { suppression: ctx.suppression, allowed_emails: published, override_to: req.override_to === true });
  if (!v.ok) return { response: { ok: false, status: 'invalid_draft', error: 'borrador_invalido', message: 'El borrador no se puede guardar: ' + v.errors.join('; ') + '.', errors: v.errors }, writes: [] };
  // Un primer correo a un dominio sin registros MX rebota seguro (3 de los 5 rebotes de octubre). ctx.mx = { domain, status, n } lo trae el motor desde DNS-over-HTTPS; si no llegó, no bloquea.
  if (kind === 'initial' && ctx.mx && ctx.mx.domain && ctx.mx.domain === emailDomain(to) && ctx.mx.n === 0 && (ctx.mx.status === 0 || ctx.mx.status === 3) && req.skip_mx !== true) return { response: { ok: false, status: 'invalid_draft', error: 'dominio_sin_mx', message: 'El dominio de ' + to + ' no tiene servidor de correo (sin registros MX): el correo rebotaría. Busca otro contacto de la empresa.', errors: ['dominio sin servidor de correo (MX)'] }, writes: [] };
  const isCold = kind !== 'reply';
  const cold = cmNormCold(req.cold);
  let lint = null;
  if (isCold) {
    const peers = (ctx.peers || []).filter((p) => p.candidate_id !== cand.id && (!live || p.id !== live.id));
    lint = coldLint({ subject, body, kind, strict: req.auto === true }, peers, cold);
    if (lint.hard.length) return { response: { ok: false, status: 'invalid_draft', error: 'borrador_invalido', message: 'El borrador no se puede guardar: ' + lint.hard.join('; ') + '.', errors: lint.hard, cold: { score: lint.score } }, writes: [] };
    if (req.auto === true) {
      if (kind === 'initial' && !cold.evidence.length) return { response: { ok: false, status: 'needs_evidence', error: 'sin_evidencia', message: 'Un borrador automático necesita evidence (1–3 hechos verificados del prospecto que respaldan lo que dice el correo). Agrégala y vuelve a guardarlo.', safety: { messages_sent: 0 } }, writes: [] };
      const min = Number(req.min_score) > 0 ? Number(req.min_score) : 70;
      if (lint.score < min) return { response: { ok: false, status: 'low_quality', error: 'calidad_baja', score: lint.score, min_score: min, level: lint.level, message: 'El correo quedó con score ' + lint.score + ' (mínimo ' + min + '): NO se guardó. Reescríbelo corrigiendo los avisos y vuelve a llamar a save_draft.', warnings: lint.warnings.slice(0, 6).map((w) => w.text), safety: { messages_sent: 0 } }, writes: [] };
    }
