  const bodyText = String(msg.body || '').trim();
  const text = bodyText + '\n\nSaludos cordiales,\n\n' + name + '\n' + title + ' · Atacama Labs\nhttps://atacamalabs.cl | ' + sigEmail + '\n\n--\n' + (legal ? legal + '\n' : '') + unsub;
